-- No client registrations or delegation grants are seeded.
ALTER TABLE hs_data_operations ADD COLUMN IF NOT EXISTS source_app text NOT NULL DEFAULT 'holy-sheet';
UPDATE hs_data_operations SET source_app='holy-sheet-import' WHERE batch_id IS NOT NULL AND source_app='holy-sheet';
ALTER TABLE hs_data_events ADD COLUMN IF NOT EXISTS service_subject text;
ALTER TABLE hs_data_change_events ADD COLUMN IF NOT EXISTS source_app text NOT NULL DEFAULT 'holy-sheet';
ALTER TABLE hs_data_change_events ADD COLUMN IF NOT EXISTS actor_id text;
ALTER TABLE hs_data_change_events ADD COLUMN IF NOT EXISTS service_subject text;
ALTER TABLE hs_data_change_events ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'record.changed';
ALTER TABLE hs_data_change_events ADD COLUMN IF NOT EXISTS sequence bigint GENERATED BY DEFAULT AS IDENTITY;
UPDATE hs_data_change_events c SET source_app=e.source_app,actor_id=e.actor_id,kind=e.kind FROM hs_data_events e WHERE e.id=c.id AND c.actor_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS hs_data_change_sequence ON hs_data_change_events(sequence);
CREATE INDEX IF NOT EXISTS hs_data_change_tenant_sequence ON hs_data_change_events(tenant_id,sequence);
CREATE TABLE IF NOT EXISTS hs_data_client_cursors (
 token_hash text PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),workspace_id text NOT NULL REFERENCES hs_workspaces(id),actor_id text NOT NULL REFERENCES hs_users(id),client_id text NOT NULL,scope_hash text NOT NULL,last_sequence bigint NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '5 minutes'
);
CREATE TABLE IF NOT EXISTS hs_data_reference_operations (
 tenant_id uuid NOT NULL REFERENCES hs_data_tenants(id),actor_id text NOT NULL REFERENCES hs_users(id),client_id text NOT NULL,operation_id uuid NOT NULL,request_hash text NOT NULL,reference_id uuid NOT NULL,record_id uuid NOT NULL,action text NOT NULL,PRIMARY KEY(tenant_id,actor_id,client_id,operation_id),FOREIGN KEY(tenant_id,record_id) REFERENCES hs_data_records(tenant_id,id)
);
CREATE OR REPLACE FUNCTION hs_data_reference_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.record_id<>OLD.record_id OR NEW.source_app<>OLD.source_app OR NEW.source_type<>OLD.source_type OR NEW.source_id<>OLD.source_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reference identity is immutable'; END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS hs_data_reference_identity_guard ON hs_data_references;
CREATE TRIGGER hs_data_reference_identity_guard BEFORE UPDATE ON hs_data_references FOR EACH ROW EXECUTE FUNCTION hs_data_reference_identity_guard();

DROP TRIGGER IF EXISTS hs_data_change_events_immutable ON hs_data_change_events;
CREATE TRIGGER hs_data_change_events_immutable BEFORE UPDATE OR DELETE ON hs_data_change_events FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
